import React, { useRef, useState, useEffect } from "react";
import "./VideoCarousel.css"; // 👈 make sure this file exists

export default function VideoCarousel() {
  const videos = [
    "/assets/banner1.mp4",
    "/assets/banner2.mp4",
    "/assets/banner3.mp4",
    "/assets/banner4.mp4",
  ];

  const [index, setIndex] = useState(0);
  const [playing, setPlaying] = useState(false);
  const vRef = useRef(null);

  useEffect(() => {
    if (vRef.current) {
      if (playing) vRef.current.play();
      else vRef.current.pause();
    }
  }, [index, playing]);

  const togglePlay = () => setPlaying((p) => !p);
  const next = () => {
    setIndex((i) => (i + 1) % videos.length);
    setPlaying(false);
  };
  const prev = () => {
    setIndex((i) => (i - 1 + videos.length) % videos.length);
    setPlaying(false);
  };

  return (
    <section className="video-banner">
      <video
        ref={vRef}
        key={videos[index]}
        src={videos[index]}
        className="banner-video"
        playsInline
        muted
        controls={false}
      />

      {/* Prev / Next Buttons */}
      <button className="vc-btn prev" onClick={prev}>
        ‹
      </button>
      <button className="vc-btn next" onClick={next}>
        ›
      </button>

      {/* Play / Pause Button */}
      <button className="play-overlay" onClick={togglePlay}>
        {playing ? "❚❚" : "►"}
      </button>

      {/* Video index indicator */}
      <div className="video-index">
        {index + 1}/{videos.length}
      </div>
    </section>
  );
}
